impl ContentEq for Expression<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Nil(_), Self::Nil(_))
            | (Self::False(_), Self::False(_))
            | (Self::True(_), Self::True(_))
            | (Self::VarArg(_), Self::VarArg(_))
            | (Self::Error(_), Self::Error(_)) => true,
            (Self::Number(lhs), Self::Number(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Integer(lhs), Self::Integer(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::StringLiteral(lhs), Self::StringLiteral(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::FunctionDef(lhs), Self::FunctionDef(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Name(lhs), Self::Name(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Suffixed(lhs), Self::Suffixed(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Parenthesized(lhs), Self::Parenthesized(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::TableConstructor(lhs), Self::TableConstructor(rhs)) => {
                ContentEq::content_eq(lhs, rhs)
            }
            (Self::BinaryOp(lhs), Self::BinaryOp(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::UnaryOp(lhs), Self::UnaryOp(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::IfExpression(lhs), Self::IfExpression(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::InterpolatedString(lhs), Self::InterpolatedString(rhs)) => {
                ContentEq::content_eq(lhs, rhs)
            }
            (Self::TypeCast(lhs), Self::TypeCast(rhs)) => ContentEq::content_eq(lhs, rhs),
            (
                Self::Nil(_)
                | Self::False(_)
                | Self::True(_)
                | Self::Number(_)
                | Self::Integer(_)
                | Self::StringLiteral(_)
                | Self::VarArg(_)
                | Self::FunctionDef(_)
                | Self::Name(_)
                | Self::Suffixed(_)
                | Self::Parenthesized(_)
                | Self::TableConstructor(_)
                | Self::BinaryOp(_)
                | Self::UnaryOp(_)
                | Self::IfExpression(_)
                | Self::InterpolatedString(_)
                | Self::TypeCast(_)
                | Self::Error(_),
                _,
            ) => false,
        }
    }
}

impl ContentEq for Var<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Name(lhs), Self::Name(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Suffixed(lhs), Self::Suffixed(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Name(_) | Self::Suffixed(_), _) => false,
        }
    }
}

impl ContentEq for SuffixedExpression<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.prefix, &other.prefix)
            && ContentEq::content_eq(&self.suffixes, &other.suffixes)
    }
}

impl ContentEq for Suffix<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Field(lhs), Self::Field(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Index { index: lhs_index, .. }, Self::Index { index: rhs_index, .. }) => {
                ContentEq::content_eq(lhs_index, rhs_index)
            }
            (Self::Call(lhs), Self::Call(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::MethodCall(lhs), Self::MethodCall(rhs)) => ContentEq::content_eq(lhs, rhs),
            (
                Self::TypeInstantiation { type_args: lhs_type_args, .. },
                Self::TypeInstantiation { type_args: rhs_type_args, .. },
            ) => ContentEq::content_eq(lhs_type_args, rhs_type_args),
            (
                Self::Field(_)
                | Self::Index { .. }
                | Self::Call(_)
                | Self::MethodCall(_)
                | Self::TypeInstantiation { .. },
                _,
            ) => false,
        }
    }
}

impl ContentEq for MethodCall<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.name, &other.name)
            && ContentEq::content_eq(&self.type_args, &other.type_args)
            && ContentEq::content_eq(&self.args, &other.args)
    }
}

impl ContentEq for FunctionArgs<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (
                Self::Parenthesized { args: lhs_args, .. },
                Self::Parenthesized { args: rhs_args, .. },
            ) => ContentEq::content_eq(lhs_args, rhs_args),
            (Self::TableConstructor(lhs), Self::TableConstructor(rhs)) => {
                ContentEq::content_eq(lhs, rhs)
            }
            (Self::StringLiteral(lhs), Self::StringLiteral(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Error(_), Self::Error(_)) => true,
            (
                Self::Parenthesized { .. }
                | Self::TableConstructor(_)
                | Self::StringLiteral(_)
                | Self::Error(_),
                _,
            ) => false,
        }
    }
}

