impl ContentEq for Field<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (
                Self::Bracketed { key: lhs_key, value: lhs_value, .. },
                Self::Bracketed { key: rhs_key, value: rhs_value, .. },
            ) => {
                ContentEq::content_eq(lhs_key, rhs_key)
                    && ContentEq::content_eq(lhs_value, rhs_value)
            }
            (
                Self::Named { name: lhs_name, value: lhs_value },
                Self::Named { name: rhs_name, value: rhs_value },
            ) => {
                ContentEq::content_eq(lhs_name, rhs_name)
                    && ContentEq::content_eq(lhs_value, rhs_value)
            }
            (Self::Positional(lhs), Self::Positional(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Bracketed { .. } | Self::Named { .. } | Self::Positional(_), _) => false,
        }
    }
}

