impl ContentEq for Type<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Name(lhs), Self::Name(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Named(lhs), Self::Named(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Typeof(lhs), Self::Typeof(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Table(lhs), Self::Table(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Function(lhs), Self::Function(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Optional(lhs), Self::Optional(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Union(lhs), Self::Union(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Intersection(lhs), Self::Intersection(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Parenthesized(lhs), Self::Parenthesized(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Pack(lhs), Self::Pack(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Nil(_), Self::Nil(_))
            | (Self::True(_), Self::True(_))
            | (Self::False(_), Self::False(_))
            | (Self::Error(_), Self::Error(_)) => true,
            (Self::StringLiteral(lhs), Self::StringLiteral(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::Variadic(lhs), Self::Variadic(rhs)) => ContentEq::content_eq(lhs, rhs),
            (Self::GenericPack(lhs), Self::GenericPack(rhs)) => ContentEq::content_eq(lhs, rhs),
            (
                Self::Name(_)
                | Self::Named(_)
                | Self::Typeof(_)
                | Self::Table(_)
                | Self::Function(_)
                | Self::Optional(_)
                | Self::Union(_)
                | Self::Intersection(_)
                | Self::Parenthesized(_)
                | Self::Pack(_)
                | Self::Nil(_)
                | Self::True(_)
                | Self::False(_)
                | Self::StringLiteral(_)
                | Self::Variadic(_)
                | Self::GenericPack(_)
                | Self::Error(_),
                _,
            ) => false,
        }
    }
}

