impl ContentEq for TypeField<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (
                Self::Named { access: lhs_access, name: lhs_name, value: lhs_value, .. },
                Self::Named { access: rhs_access, name: rhs_name, value: rhs_value, .. },
            ) => {
                ContentEq::content_eq(lhs_access, rhs_access)
                    && ContentEq::content_eq(lhs_name, rhs_name)
                    && ContentEq::content_eq(lhs_value, rhs_value)
            }
            (
                Self::Indexer { access: lhs_access, key: lhs_key, value: lhs_value, .. },
                Self::Indexer { access: rhs_access, key: rhs_key, value: rhs_value, .. },
            ) => {
                ContentEq::content_eq(lhs_access, rhs_access)
                    && ContentEq::content_eq(lhs_key, rhs_key)
                    && ContentEq::content_eq(lhs_value, rhs_value)
            }
            (
                Self::Array { access: lhs_access, value: lhs_value, .. },
                Self::Array { access: rhs_access, value: rhs_value, .. },
            ) => {
                ContentEq::content_eq(lhs_access, rhs_access)
                    && ContentEq::content_eq(lhs_value, rhs_value)
            }
            (Self::Named { .. } | Self::Indexer { .. } | Self::Array { .. }, _) => false,
        }
    }
}

impl ContentEq for TypeFieldAccess {
    fn content_eq(&self, other: &Self) -> bool {
        self == other
    }
}

impl ContentEq for FunctionType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.generics, &other.generics)
            && ContentEq::content_eq(&self.params, &other.params)
            && ContentEq::content_eq(&self.return_type, &other.return_type)
    }
}

impl ContentEq for FunctionTypeParam<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.name, &other.name) && ContentEq::content_eq(&self.ty, &other.ty)
    }
}

impl ContentEq for OptionalType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.ty, &other.ty)
            && ContentEq::content_eq(&self.question_count, &other.question_count)
    }
}

impl ContentEq for UnionType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.types, &other.types)
    }
}

impl ContentEq for IntersectionType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.types, &other.types)
    }
}

impl ContentEq for ParenthesizedType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.ty, &other.ty)
    }
}

impl ContentEq for TypePack<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.types, &other.types)
    }
}

impl ContentEq for VariadicType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.ty, &other.ty)
    }
}

impl ContentEq for GenericPackType<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.name, &other.name)
    }
}

impl ContentEq for GenericTypeList<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.params, &other.params)
    }
}

impl ContentEq for GenericTypeParam<'_> {
    fn content_eq(&self, other: &Self) -> bool {
        ContentEq::content_eq(&self.name, &other.name)
            && ContentEq::content_eq(&self.is_pack, &other.is_pack)
            && ContentEq::content_eq(&self.default, &other.default)
    }
}
